#!/usr/bin/env bash
# Regenerate the hashed dependency locks for every Python service.
#
#   services/lock-requirements.sh              # all services
#   services/lock-requirements.sh sidecar      # one service
#
# HOW DEPENDENCIES ARE MANAGED (one convention, every Python service):
#
#   requirements.txt   Human-edited. DIRECT dependencies only, each pinned
#                      exactly (==). This is what you change to bump a
#                      package, and what CI's fast test jobs install.
#   requirements.lock  Generated by this script - never hand-edit. The FULL
#                      transitive tree, every package pinned exactly and
#                      carrying the sha256 of every published artifact for
#                      that version. Each Dockerfile installs ONLY this file,
#                      with `pip install --require-hashes`, so an image build
#                      can neither float to a different transitive version
#                      nor accept a tampered/replaced wheel.
#
# The lock is "universal" (uv pip compile --universal): one file valid for
# linux/amd64 AND linux/arm64 (and the dev laptops), with environment markers
# instead of per-platform files - the image is built for both architectures.
# It targets Python 3.12, the interpreter every service image runs
# (python:3.12.14-slim-bookworm).
#
# To bump a dependency: edit requirements.txt, run this script, run
# `pip-audit -r <service>/requirements.lock` and the service's tests, commit
# both files together.
#
# sidecar is the one special case: torch is installed from PyTorch's CPU-only
# wheel index (see sidecar/Dockerfile for why - it avoids ~1.5 GB of unused
# CUDA libraries). sidecar/lock/pyproject.toml pins torch to the +cpu local
# version and scopes that index to torch ALONE (explicit index + source), so
# every other package's hashes still come from PyPI.
#
# Requires uv (https://docs.astral.sh/uv/) - `pip install uv` or the
# standalone installer. Network access to PyPI (and download.pytorch.org for
# sidecar) is needed; nothing is installed locally.
set -euo pipefail

cd "$(dirname "$0")"

PY_VERSION=3.12
ALL=(app-builder code-intel rl-trainer sidecar tool-sandbox voice-agent)

if [ "$#" -gt 0 ]; then
  SERVICES=("$@")
else
  SERVICES=("${ALL[@]}")
fi

for svc in "${SERVICES[@]}"; do
  echo "==> $svc"
  inputs=("$svc/requirements.txt")
  if [ "$svc" = "sidecar" ]; then
    inputs=("$svc/lock/pyproject.toml" "${inputs[@]}")
  fi
  # <service>/overrides.txt, when present, forces versions past a dependency's own
  # bounds (uv --override); each line there carries its reason. Such a service's
  # Dockerfile installs its lock with --no-deps, since pip would otherwise refuse
  # the overridden pin against that dependency's declared range.
  overrides=()
  if [ -f "$svc/overrides.txt" ]; then
    overrides=(--override "$svc/overrides.txt")
  fi
  uv pip compile "${inputs[@]}" \
    --universal \
    --python-version "$PY_VERSION" \
    --generate-hashes \
    "${overrides[@]}" \
    --custom-compile-command "services/lock-requirements.sh $svc" \
    --output-file "$svc/requirements.lock"
done
